// Third-person characters. Models live in public/models/<id>.glb and are generated by
// tools/build-characters.mjs. They all share joint names (Hips, Spine, Head, Muzzle, …) and
// two animation clips ("Idle", "Run"), so any of them can be dropped onto any soldier.
// Models face -Z; set group.rotation.y = yaw.

import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { TEAM_INFO, PLAYER } from '@shared/config.js';

export const CHARACTER_IDS = ['trooper', 'scout', 'heavy', 'specter'];

const MODEL_SCALE = (PLAYER.height / 1.86) * 0.99; // helmets top out around 1.86 m in the source files
const FLASH = new THREE.MeshBasicMaterial({ color: 0xfff1a8 });
const flashGeo = new THREE.BoxGeometry(0.22, 0.22, 0.32);
const templates = {};      // id -> { scene, clips }
const teamMatCache = new Map();

/** Materials named Team / TeamAccent / Glow in the GLB are recoloured for each team. */
function teamMaterial(src, team) {
  const key = team + ':' + src.uuid;
  let m = teamMatCache.get(key);
  if (m) return m;
  const base = new THREE.Color(TEAM_INFO[team].color);
  const accent = base.clone().lerp(new THREE.Color(0xffffff), 0.45);
  m = src.clone();
  if (src.name === 'Team') m.color.copy(base);
  else {
    m.color.copy(accent);
    if (src.name === 'Glow') m.emissive.copy(accent);
  }
  teamMatCache.set(key, m);
  return m;
}

function loadOne(loader, id) {
  return new Promise((resolve) => {
    loader.load(
      `${import.meta.env.BASE_URL}models/${id}.glb`,
      (gltf) => {
        gltf.scene.traverse((o) => { if (o.isMesh) o.castShadow = true; });
        templates[id] = { scene: gltf.scene, clips: gltf.animations };
        resolve(true);
      },
      undefined,
      (e) => { console.error(`[character] could not load ${id}.glb`, e); resolve(false); },
    );
  });
}

/** Load every character once. Resolves to the number that loaded successfully. */
export async function loadCharacters() {
  const loader = new GLTFLoader();
  const ok = await Promise.all(CHARACTER_IDS.map((id) => loadOne(loader, id)));
  return ok.filter(Boolean).length;
}

// ---- fallback: a simple box soldier, only used if a GLB fails to load ----
function buildFallback(team) {
  const box = new THREE.BoxGeometry(1, 1, 1);
  const suit = new THREE.MeshLambertMaterial({ color: 0x343848 });
  const teamMat = new THREE.MeshLambertMaterial({ color: TEAM_INFO[team].color });
  const node = (name, parent, x, y, z) => { const g = new THREE.Group(); g.name = name; g.position.set(x, y, z); parent.add(g); return g; };
  const part = (parent, mat, w, h, d, x, y, z) => { const m = new THREE.Mesh(box, mat); m.scale.set(w, h, d); m.position.set(x, y, z); m.castShadow = true; parent.add(m); };
  const rig = new THREE.Group();
  part(rig, suit, 0.2, 0.86, 0.22, -0.13, 0.43, 0);
  part(rig, suit, 0.2, 0.86, 0.22, 0.13, 0.43, 0);
  const spine = node('Spine', rig, 0, 0.9, 0);
  part(spine, teamMat, 0.5, 0.58, 0.28, 0, 0.27, 0);
  part(spine, suit, 0.07, 0.11, 0.7, 0.12, 0.3, -0.45);
  node('Muzzle', spine, 0.12, 0.3, -0.85);
  const head = node('Head', spine, 0, 0.56, 0);
  part(head, teamMat, 0.3, 0.32, 0.3, 0, 0.17, 0);
  return rig;
}

export class SoldierModel {
  constructor(team, id = CHARACTER_IDS[0]) {
    const tpl = templates[id] || Object.values(templates)[0];
    if (tpl) {
      this.group = tpl.scene.clone(true);
      this.group.scale.setScalar(MODEL_SCALE);
      this.group.traverse((o) => {
        const n = o.isMesh && o.material.name;
        if (n === 'Team' || n === 'TeamAccent' || n === 'Glow') o.material = teamMaterial(o.material, team);
      });
      this.mixer = new THREE.AnimationMixer(this.group);
      const clip = (name) => THREE.AnimationClip.findByName(tpl.clips, name);
      this.idle = this.mixer.clipAction(clip('Idle'));
      this.run = this.mixer.clipAction(clip('Run'));
      this.idle.play();
      this.run.play();
      this.mixer.setTime(Math.random() * 3); // so squads don't move in lockstep
    } else {
      this.group = buildFallback(team);
      this.mixer = null;
    }
    this.spine = this.group.getObjectByName('Spine');
    this.head = this.group.getObjectByName('Head');
    this.flash = new THREE.Mesh(flashGeo, FLASH);
    this.flash.visible = false;
    this.flash.position.z = -0.16;
    this.group.getObjectByName('Muzzle').add(this.flash);
    this.runW = 0;
    this.flashT = 0;
  }

  muzzleFlash() { this.flashT = 0.05; }

  update(s, dt) {
    const g = this.group;
    g.visible = s.alive;
    if (!s.alive) return;
    const b = s.body;
    g.position.set(b.x, b.y, b.z);
    g.rotation.y = s.yaw;

    const speed = Math.hypot(b.vx, b.vz);
    if (this.mixer) {
      // blend Idle <-> Run by how fast the soldier is moving
      const target = b.grounded ? Math.min(1, speed / 4) : 0.7;
      this.runW += (target - this.runW) * (1 - Math.exp(-10 * dt));
      this.idle.setEffectiveWeight(1 - this.runW);
      this.run.setEffectiveWeight(this.runW);
      this.run.timeScale = THREE.MathUtils.clamp(speed / 6.2, 0.6, 1.5);
      this.mixer.update(dt);
    }
    // aim: tilt the upper body (arms + rifle hang off the spine) on top of the animation
    this.spine.rotateX(s.pitch * 0.75);
    this.head.rotateX(s.pitch * 0.25);

    if (this.flashT > 0) {
      this.flashT -= dt;
      this.flash.visible = true;
      this.flash.rotation.z = Math.random() * 3;
    } else this.flash.visible = false;
  }
}
